class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        int count[1001] = {0};
        for (int x : nums1) {
            count[x]++;
        }
        vector<int> res;
        for (int x : nums2) {
            if (count[x] > 0) {
                res.push_back(x);
                count[x]--;
            }
        }
        return res;
    }
};
